            app_id: AppInstanceId(record.id.clone()),
            actor: "bench".to_string(),
            config: serde_json::to_vec(&record.scale_fixture).unwrap_or_default(),
            assets: Vec::new(),
            capabilities: Vec::new(),
            quotas: QuotaSchema::default(),
        }
    }
