#[cfg(not(target_arch = "wasm32"))]
struct FrameExecutionOwnerCell<T> {
    state: std::sync::atomic::AtomicU8,
    owner: std::cell::UnsafeCell<Option<T>>,
}

#[cfg(not(target_arch = "wasm32"))]
unsafe impl<T: Send> Send for FrameExecutionOwnerCell<T> {}

#[cfg(not(target_arch = "wasm32"))]
unsafe impl<T: Send> Sync for FrameExecutionOwnerCell<T> {}

#[cfg(not(target_arch = "wasm32"))]
impl<T> FrameExecutionOwnerCell<T> {
    fn new(owner: T) -> Self {
        Self { state: std::sync::atomic::AtomicU8::new(0), owner: std::cell::UnsafeCell::new(Some(owner)) }
    }

    fn try_take(&self) -> Option<T> {
        self.state.compare_exchange(0, 1, Ordering::AcqRel, Ordering::Acquire).ok()?;
        unsafe { (&mut *self.owner.get()).take() }
    }

    fn try_restore(&self, owner: T) -> Result<(), T> {
        if self.state.load(Ordering::Acquire) != 1 {
            return Err(owner);
        }
        let slot = unsafe { &mut *self.owner.get() };
        if slot.is_some() {
            return Err(owner);
        }
        *slot = Some(owner);
        self.state.store(0, Ordering::Release);
        Ok(())
    }

    fn restore_taken(&self, owner: T) {
        unsafe {
            *self.owner.get() = Some(owner);
        }
        self.state.store(0, Ordering::Release);
    }
}

#[cfg(not(target_arch = "wasm32"))]
struct FrameMaintenanceRefusal {
    owner: Arc<FrameExecutionOwnerCell<FrameMaintenanceOwner>>,
    reservation_live: bool,
}

#[cfg(not(target_arch = "wasm32"))]
impl FrameMaintenanceRefusal {
    fn try_take(&self) -> Option<FrameMaintenanceOwner> {
        self.owner.try_take()
    }
}

#[cfg(not(target_arch = "wasm32"))]
struct FrameExecutionRegistry<T> {
    state: std::sync::atomic::AtomicU8,
    generation: AtomicU64,
    owner: std::cell::UnsafeCell<Option<Arc<FrameExecutionOwnerCell<T>>>>,
}

#[cfg(not(target_arch = "wasm32"))]
unsafe impl<T: Send> Send for FrameExecutionRegistry<T> {}

#[cfg(not(target_arch = "wasm32"))]
unsafe impl<T: Send> Sync for FrameExecutionRegistry<T> {}

#[cfg(not(target_arch = "wasm32"))]
impl<T> FrameExecutionRegistry<T> {
    const WRITING: u8 = 1;
    const QUEUED: u8 = 2;
    const RUNNING: u8 = 3;
    const ABANDONED: u8 = 4;
    const RECOVERING: u8 = 5;

    fn new() -> Self {
        Self { state: std::sync::atomic::AtomicU8::new(0), generation: AtomicU64::new(0), owner: std::cell::UnsafeCell::new(None) }
    }

    fn try_publish(&self, generation: u64, owner: Arc<FrameExecutionOwnerCell<T>>) -> Result<(), Arc<FrameExecutionOwnerCell<T>>> {
        if self.state.compare_exchange(0, Self::WRITING, Ordering::AcqRel, Ordering::Acquire).is_err() {
            return Err(owner);
        }
        unsafe {
            *self.owner.get() = Some(owner);
        }
        self.generation.store(generation, Ordering::Release);
        self.state.store(Self::QUEUED, Ordering::Release);
        Ok(())
    }

    fn try_begin(&self, generation: u64) -> Option<Arc<FrameExecutionOwnerCell<T>>> {
        if self.generation.load(Ordering::Acquire) != generation {
            return None;
        }
        self.state.compare_exchange(Self::QUEUED, Self::RUNNING, Ordering::AcqRel, Ordering::Acquire).ok()?;
        unsafe { (&*self.owner.get()).as_ref().cloned() }
    }

    fn abandon(&self, generation: u64) -> bool {
        if self.generation.load(Ordering::Acquire) != generation {
            return false;
        }
        let state = self.state.load(Ordering::Acquire);
        if !matches!(state, Self::QUEUED | Self::RUNNING) {
            return false;
        }
        self.state.compare_exchange(state, Self::ABANDONED, Ordering::AcqRel, Ordering::Acquire).is_ok()
    }

    fn complete(&self, generation: u64) -> bool {
        if self.generation.load(Ordering::Acquire) != generation || self.state.compare_exchange(Self::RUNNING, Self::WRITING, Ordering::AcqRel, Ordering::Acquire).is_err() {
            return false;
        }
        let owner = unsafe { (&mut *self.owner.get()).take() };
        drop(owner);
        self.generation.store(0, Ordering::Release);
        self.state.store(0, Ordering::Release);
        true
    }

    fn reclaim_rejected(&self, generation: u64, fallback: Arc<FrameExecutionOwnerCell<T>>) -> Arc<FrameExecutionOwnerCell<T>> {
        if self.generation.load(Ordering::Acquire) != generation {
            return fallback;
        }
        if self.state.compare_exchange(Self::QUEUED, Self::RECOVERING, Ordering::AcqRel, Ordering::Acquire).is_err() {
            return fallback;
        }
        let owner = unsafe { (&mut *self.owner.get()).take() };
        self.generation.store(0, Ordering::Release);
        self.state.store(0, Ordering::Release);
        match owner {
            Some(owner) => owner,
            None => fallback,
        }
    }

    fn try_take_abandoned(&self) -> Option<(u64, Arc<FrameExecutionOwnerCell<T>>)> {
        self.state.compare_exchange(Self::ABANDONED, Self::RECOVERING, Ordering::AcqRel, Ordering::Acquire).ok()?;
        let generation = self.generation.load(Ordering::Acquire);
        let owner = unsafe { (&mut *self.owner.get()).take() }?;
        self.generation.store(0, Ordering::Release);
        self.state.store(0, Ordering::Release);
        Some((generation, owner))
    }
}

#[cfg(not(target_arch = "wasm32"))]
struct FrameMaintenanceAuthority {
    state: std::sync::atomic::AtomicU8,
    generation: AtomicU64,
}

#[cfg(not(target_arch = "wasm32"))]
impl FrameMaintenanceAuthority {
    fn new() -> Self {
        Self { state: std::sync::atomic::AtomicU8::new(0), generation: AtomicU64::new(0) }
    }

    fn try_reserve(&self, generation: u64) -> bool {
        if self.state.compare_exchange(0, 1, Ordering::AcqRel, Ordering::Acquire).is_err() {
            return false;
        }
        self.generation.store(generation, Ordering::Release);
        true
    }

    fn is_live(&self, generation: u64) -> bool {
        self.state.load(Ordering::Acquire) == 1 && self.generation.load(Ordering::Acquire) == generation
    }

    fn release(&self, generation: u64) -> bool {
        if !self.is_live(generation) {
            return false;
        }
        self.generation.store(0, Ordering::Release);
        self.state.compare_exchange(1, 0, Ordering::AcqRel, Ordering::Acquire).is_ok()
    }
}

/// 🛑️ Classifies one maintenance terminal guard before any field work moves.
#[cfg(not(target_arch = "wasm32"))]
fn frame_maintenance_terminal_fault(cancelled: bool, stale: bool, deadline_exceeded: bool) -> Option<&'static str> {
    if cancelled {
        Some("frame maintenance cancelled")
    } else if stale {
        Some("frame maintenance generation became stale")
    } else if deadline_exceeded {
        Some("frame maintenance deadline expired")
    } else {
        None
    }
}

enum RuntimeApply {
    Resize {
        width: f32,
        height: f32,
        dpr: f32,
    },
    DispatchEvents(Option<RuntimeDispatchCursor>),
    ResumeDispatch {
        interaction: Option<AppInteractionState>,
        cursor: Option<RuntimeDispatchCursor>,
    },
    ResumeFrameDeferred {
        interaction: Option<AppInteractionState>,
        cursor: Option<FrameDeferredCursor>,
    },
    #[cfg(not(target_arch = "wasm32"))]
    RestoreInteraction(Option<AppInteractionState>),
    #[cfg(not(target_arch = "wasm32"))]
    PluginReload(Option<Result<Vec<program_bridge::ProgramBridgeEntry>, String>>),
}

impl RuntimeApply {
    fn close_returned_interaction_step(&mut self, runtime: &mut AppRuntime) -> bool {
        match self {
            Self::ResumeFrameDeferred { interaction, cursor } => {
                if let Some(returned) = interaction.take() {
                    runtime.return_interaction(returned);
                    return false;
                }
                if let Some(owner) = cursor.as_mut() {
                    owner.begin_close();
                    if !owner.close_step() {
                        return false;
                    }
                }
                cursor.take();
                true
            }
            Self::ResumeDispatch { interaction, cursor } => {
                if let Some(returned) = interaction.take() {
                    runtime.return_interaction(returned);
                    return false;
                }
                if cursor.as_mut().is_some_and(|owner| !owner.close_step()) {
                    return false;
                }
                cursor.take();
                true
            }
            #[cfg(not(target_arch = "wasm32"))]
            Self::RestoreInteraction(interaction) => {
                if let Some(returned) = interaction.take() {
                    runtime.return_interaction(returned);
                }
                true
            }
            _ => false,
        }
    }

    /// 🎟️ Whether applying this completion HANDS THE INTERACTION STATE BACK. The checkout ledger ages
    /// a live checkout against exactly this: while one of these is queued (or a reservation for one is
    /// in flight) the state has an owner, and however long that owner takes it is not a leak. An arm
    /// that carries no state carries no ownership either — the native abandoned-maintenance resume is
    /// `ResumeFrameDeferred { interaction: None, .. }` for that reason.
    fn restores_interaction(&self) -> bool {
        match self {
            Self::ResumeDispatch { interaction, .. } | Self::ResumeFrameDeferred { interaction, .. } => interaction.is_some(),
            #[cfg(not(target_arch = "wasm32"))]
            Self::RestoreInteraction(interaction) => interaction.is_some(),
            _ => false,
        }
    }

    fn restore_interaction_only(&mut self, runtime: &mut AppRuntime) -> bool {
        match self {
            Self::ResumeDispatch { interaction, cursor } => {
                let Some(returned) = interaction.take() else { return cursor.is_none() };
                runtime.return_interaction(returned);
                cursor.is_none()
            }
            Self::ResumeFrameDeferred { interaction, cursor } => {
                let Some(returned) = interaction.take() else { return cursor.is_none() };
                runtime.return_interaction(returned);
                cursor.is_none()
            }
            #[cfg(not(target_arch = "wasm32"))]
            Self::RestoreInteraction(interaction) => {
                let Some(returned) = interaction.take() else { return true };
                runtime.return_interaction(returned);
                true
            }
            _ => false,
        }
    }

    fn start_dispatch(cursor: &mut Option<RuntimeDispatchCursor>, runtime: &mut AppRuntime, handle: &AppHandle) -> bool {
        log_debug("[TRACE] start_dispatch enter");
        let Some(cursor_value) = cursor.as_mut() else { return true };
        if cursor_value.terminal_is_empty() {
            cursor.take();
            return true;
        }
        let Some(mailbox) = handle.upgrade().map(RuntimeMailbox) else {
            log_debug("[TRACE] start_dispatch refused: mailbox handle expired");
            return false;
        };
        let Some(mut interaction) = runtime.check_out_interaction("dispatch-event") else {
            log_debug_once_per_transition("start-dispatch-checkout", true, "[TRACE] start_dispatch refused: interaction state is checked out");
            return false;
        };
        log_debug_once_per_transition("start-dispatch-checkout", false, "[TRACE] start_dispatch: interaction state checked out for one event");
        if !mailbox.reserve_interaction_future() {
            log_debug("[TRACE] start_dispatch refused: interaction future credits exhausted");
            interaction.frame_fault = Some("runtime dispatch completion credits exhausted".to_string());
            runtime.return_interaction(interaction);
            return false;
        }
        let mut cursor_value = cursor.take().expect("dispatch cursor admitted above");
        let event = cursor_value.take_next().expect("non-empty dispatch cursor");
        mailbox.spawn_dispatch_reserved(async move {
            let _latency = frame_latency::FrameLatencyTimer::start(frame_latency::FrameLatencyAuthority::renderer_frame(cursor_value.generation), frame_latency::FrameLatencyStage::DispatchApply, 1);
            winit_app::dispatch_normalized_event(&mut interaction, event).await;
            (interaction, cursor_value)
        });
        true
    }

    fn start_frame_deferred(cursor: &mut Option<FrameDeferredCursor>, runtime: &mut AppRuntime, handle: &AppHandle) -> bool {
        #[cfg(not(target_arch = "wasm32"))]
        if cursor.is_none() && !runtime.interaction_available() {
            if let Some(mailbox) = handle.upgrade().map(RuntimeMailbox) {
                if let Some(mut owner) = mailbox.try_take_abandoned_frame_deferred() {
                    owner.cancel_current();
                    let Some((interaction, returned_cursor)) = owner.take_pair() else { return false };
                    runtime.return_interaction(interaction);
                    *cursor = Some(returned_cursor);
                    return false;
                }
            }
        }
        #[cfg(not(target_arch = "wasm32"))]
        if runtime.pending_frame_maintenance_refusal.is_none() {
            if let Some(mailbox) = handle.upgrade().map(RuntimeMailbox) {
                runtime.pending_frame_maintenance_refusal = mailbox.try_take_abandoned_frame_maintenance();
            }
        }
        #[cfg(not(target_arch = "wasm32"))]
        if let Some(mut refusal) = runtime.pending_frame_maintenance_refusal.take() {
            let Some(mailbox) = handle.upgrade().map(RuntimeMailbox) else {
                runtime.pending_frame_maintenance_refusal = Some(refusal);
                return false;
            };
            if refusal.reservation_live {
                if !mailbox.cancel_interaction_future_reservation() {
                    runtime.pending_frame_maintenance_refusal = Some(refusal);
                    return false;
                }
                refusal.reservation_live = false;
            }
            let Some(mut owner) = refusal.try_take() else {
                runtime.pending_frame_maintenance_refusal = Some(refusal);
                return false;
            };
            let Some((interaction, mut returned_cursor)) = owner.take_pair() else {
                if let Err(owner) = refusal.owner.try_restore(owner) {
                    refusal.owner = Arc::new(FrameExecutionOwnerCell::new(owner));
                }
                runtime.pending_frame_maintenance_refusal = Some(refusal);
                return false;
            };
            returned_cursor.return_shell_maintenance();
            runtime.return_interaction(interaction);
            *cursor = Some(returned_cursor);
            return false;
        }
        if cursor.as_ref().is_some_and(|cursor| cursor.closing) {
            let complete = cursor.as_mut().is_some_and(FrameDeferredCursor::close_step);
            if complete {
                cursor.take();
            }
            return complete;
        }
        let Some(cursor_value) = cursor.as_mut() else { return true };
        if cursor_value.terminal_is_empty() {
            cursor.take();
            return true;
        }
        let Some(mailbox) = handle.upgrade().map(RuntimeMailbox) else { return false };
        let checkout_site = cursor_value.checkout_site();
        let Some(mut interaction) = runtime.check_out_interaction(checkout_site) else { return false };
        if !mailbox.reserve_interaction_future() {
            interaction.frame_fault = Some("frame deferred completion credits exhausted".to_string());
            runtime.return_interaction(interaction);
            return false;
        }
        let Some(mut cursor_value) = cursor.take() else {
            runtime.return_interaction(interaction);
            return false;
        };
        let Some(work) = cursor_value.take_next() else {
            runtime.return_interaction(interaction);
            if !cursor_value.terminal_is_empty() {
                cursor_value.closing = true;
                *cursor = Some(cursor_value);
                return false;
            }
            return true;
        };
        if matches!(work, FrameDeferredWork::ShellMaintenance) {
            #[cfg(not(target_arch = "wasm32"))]
            {
                match mailbox.try_spawn_frame_maintenance_reserved(FrameMaintenanceOwner::new(interaction, cursor_value)) {
                    Ok(()) => return true,
                    Err(refusal) => {
                        runtime.pending_frame_maintenance_refusal = Some(refusal);
                        return false;
                    }
                }
            }
            #[cfg(target_arch = "wasm32")]
            {
                mailbox.spawn_frame_maintenance_reserved(async move {
                    cursor_value.shell_maintenance = interaction.shell.advance_chrome_maintenance_step();
                    if cursor_value.shell_maintenance {
                        cursor_value.phase = 0;
                    }
                    (interaction, cursor_value)
                });
                return true;
            }
        }
        #[cfg(not(target_arch = "wasm32"))]
        {
            match mailbox.try_spawn_frame_deferred_reserved(FrameDeferredExecutionOwner::new(interaction, cursor_value, work)) {
                Ok(()) => return true,
                Err(mut owner) => {
                    let _ = mailbox.0.completions.lock().expect("runtime completion mailbox lock").cancel_interaction_reservation();
                    owner.cancel_current();
                    let Some((interaction, cursor_value)) = owner.take_pair() else { return false };
                    runtime.return_interaction(interaction);
                    *cursor = Some(cursor_value);
                    return false;
                }
            }
        }
        #[cfg(target_arch = "wasm32")]
        mailbox.spawn_frame_deferred_reserved(async move {
            match work {
                FrameDeferredWork::ShellMaintenance => {}
                FrameDeferredWork::PumpSync => {
                    interaction.shell.pump_sync_events().await;
                }
                FrameDeferredWork::Action(action) => {
                    if action.cancelled {
                        action.cancel();
                    } else {
                        let receipt = action.receipt;
                        let mut receipt_owner = FrameActionReceiptOwner { receipt };
                        match interaction.shell.dispatch_gesture_action(action.descriptor).await {
                            Ok(()) => {
                                receipt_owner.settle(engine_canvas::TextEditorActionOutcome::Accepted);
                            }
                            Err(error) => {
                                receipt_owner.settle(engine_canvas::TextEditorActionOutcome::Refused(&error));
                                if let Some(receipt) = receipt {
                                    if receipt.abort_correlation_on_error {
                                        cursor_value.actions.cancel_correlation(receipt.token);
                                    }
                                }
                                log_debug(&format!("[TRACE] frame deferred action failed: {error}"));
                                interaction.shell.note_dispatch_fault(&error);
                            }
                        }
                    }
                }
                FrameDeferredWork::FlushTutorial => interaction.shell.tutorial_flush_pending_document_ops().await,
                FrameDeferredWork::Settle => {
                    interaction.shell.settle_pump_step().await;
                }
            }
            (interaction, cursor_value)
        });
        #[cfg(target_arch = "wasm32")]
        return true;
        #[allow(unreachable_code)]
        false
    }

    fn apply_step(&mut self, runtime: &mut AppRuntime, handle: &AppHandle) -> bool {
        if let Self::DispatchEvents(cursor) = self {
            log_debug(&format!("[TRACE] apply_step DispatchEvents present={} terminal-empty={:?}", cursor.is_some(), cursor.as_ref().map(RuntimeDispatchCursor::terminal_is_empty)));
        }
        match self {
            Self::Resize { width, height, dpr } => runtime.resize(*width, *height, *dpr),
            Self::DispatchEvents(cursor) => return Self::start_dispatch(cursor, runtime, handle),
            Self::ResumeDispatch { interaction, cursor } => {
                if let Some(returned) = interaction.take() {
                    runtime.return_interaction(returned);
                }
                return Self::start_dispatch(cursor, runtime, handle);
            }
            Self::ResumeFrameDeferred { interaction, cursor } => {
                if let Some(returned) = interaction.take() {
                    runtime.return_interaction(returned);
                }
                return Self::start_frame_deferred(cursor, runtime, handle);
            }
            #[cfg(not(target_arch = "wasm32"))]
            Self::RestoreInteraction(interaction) => {
                if let Some(returned) = interaction.take() {
                    runtime.return_interaction(returned);
                }
            }
            #[cfg(not(target_arch = "wasm32"))]
            Self::PluginReload(result) => match result.take() {
                Some(Ok(entries)) => {
                    let handle = handle.clone();
                    runtime.submit_interaction(&handle, Some("plugin-boot"), move |mut interaction| async move {
                        interaction.shell.prepare_hot_reload(entries);
                        if let Err(error) = interaction.shell.boot().await {
                            log_debug(&format!("wasm program hot reload failed: {error}"));
                        } else {
                            log_debug("wasm program hot reload complete");
                        }
                        interaction
                    });
                }
                Some(Err(error)) => log_debug(&format!("wasm program reload failed: {error}")),
                None => return true,
            },
        }
        true
    }
}

const RUNTIME_COMPLETION_CAPACITY: usize = 128;
const WORLD3D_DEADLINE_CAPACITY: usize = 256;
const WORLD3D_DEADLINE_ID_BYTES: usize = 256;
const EFFECT_STORM_BUDGET: u32 = 64;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
struct RuntimePresentationWitness {
    scene_revision: u64,
    input_generation: u64,
}

struct RuntimePresentationAuthorityInner {
    scene_revision: AtomicU64,
    input_generation: AtomicU64,
    admitted_scene_revision: AtomicU64,
    admitted_input_generation: AtomicU64,
    admitted: AtomicBool,
}

#[derive(Clone)]
struct RuntimePresentationAuthority(Arc<RuntimePresentationAuthorityInner>);

impl RuntimePresentationAuthority {
    fn new() -> Self {
        Self(Arc::new(RuntimePresentationAuthorityInner {
            scene_revision: AtomicU64::new(1),
            input_generation: AtomicU64::new(0),
            admitted_scene_revision: AtomicU64::new(0),
            admitted_input_generation: AtomicU64::new(0),
            admitted: AtomicBool::new(false),
        }))
    }

    /// 🎟️ The witness ONE frame build was admitted under, written by that build when it mints its
    /// `FrameBuildCursor` and read by `AppPresenter::present_step`'s admission gate.
    ///
    /// **This is what makes the build and the presenter one authority instead of two.** `current()`
    /// is a moving target by design — `mark_scene_changed` fires from every runtime completion the
    /// host pumps, several per tick — so a presenter that re-read it at admission refused a packet
    /// that had been built, correctly, against the authority as it stood when the build started, and
    /// turned it into a SURFACE FAULT (`offscreen prepared frame admission: prepared render revision
    /// is stale: live=35, packet=27` → `worker-present-failed`, ticket
    /// 26/09/09/PROCEDURAL-3D-END-TO-END, `📓️wgpu-edit-convergence-perf-2026-09-14.md` §6). Freshness
    /// is the BUILD's decision — it supersedes itself the moment its own witness moves — and the
    /// presenter's gate is there to refuse a packet from some OTHER build, which this pair still
    /// catches exactly.
    ///
    /// One writer, one reader, no race: `poll_runtime_and_resubmit` admits at most one build at a
    /// time, and `redraw_core` admits the finished frame and takes its `BeginGpu` step inside the
    /// SAME host tick, before any later build can write here.
    fn admit_build(&self, witness: RuntimePresentationWitness) {
        self.0.admitted_scene_revision.store(witness.scene_revision, Ordering::Release);
        self.0.admitted_input_generation.store(witness.input_generation, Ordering::Release);
        self.0.admitted.store(true, Ordering::Release);
    }

    /// 🎟️ The pair a presentation must be admitted against — the live one until a build has ever run.
    fn admitted(&self) -> RuntimePresentationWitness {
        if !self.0.admitted.load(Ordering::Acquire) {
            return self.current();
        }
        RuntimePresentationWitness { scene_revision: self.0.admitted_scene_revision.load(Ordering::Acquire), input_generation: self.0.admitted_input_generation.load(Ordering::Acquire) }
    }

    fn mark_scene_changed(&self) {
        self.0.scene_revision.fetch_add(1, Ordering::AcqRel);
    }

    fn observe_input_generation(&self, generation: u64) {
        self.0.input_generation.store(generation, Ordering::Release);
    }

    fn current(&self) -> RuntimePresentationWitness {
        RuntimePresentationWitness { scene_revision: self.0.scene_revision.load(Ordering::Acquire), input_generation: self.0.input_generation.load(Ordering::Acquire) }
    }

    fn witness_for(&self, input_generation: u64) -> Option<RuntimePresentationWitness> {
        let witness = self.current();
        (witness.input_generation == input_generation).then_some(witness)
    }

    #[cfg(test)]
    fn matches(&self, scene_revision: u64, input_generation: u64) -> bool {
        self.current() == RuntimePresentationWitness { scene_revision, input_generation }
    }
}

struct RuntimeRasterOperationAuthorityInner {
    next_operation: AtomicU64,
    exhausted: AtomicBool,
    current: Mutex<Option<ui_wgpu::wgpu::RasterTextureWitness>>,
}

#[derive(Clone)]
struct RuntimeRasterOperationAuthority(Arc<RuntimeRasterOperationAuthorityInner>);

impl RuntimeRasterOperationAuthority {
    fn new() -> Self {
        Self(Arc::new(RuntimeRasterOperationAuthorityInner { next_operation: AtomicU64::new(1), exhausted: AtomicBool::new(false), current: Mutex::new(None) }))
    }

    fn begin(&self, scene_revision: u64, preview_generation: u64) -> Result<ui_wgpu::wgpu::RasterTextureWitness, &'static str> {
        let mut current = self.0.current.lock().map_err(|_| "raster operation authority was poisoned")?;
        if current.is_some() {
            return Err("raster operation authority was occupied");
        }
        let operation = loop {
            if self.0.exhausted.load(Ordering::Acquire) {
                return Err("raster operation generation exhausted");
            }
            let operation = self.0.next_operation.load(Ordering::Acquire);
            if operation == u64::MAX {
                if self.0.exhausted.compare_exchange(false, true, Ordering::AcqRel, Ordering::Acquire).is_ok() {
                    break operation;
                }
                continue;
            }
            if self.0.next_operation.compare_exchange(operation, operation + 1, Ordering::AcqRel, Ordering::Acquire).is_ok() {
                break operation;
            }
        };
        let witness = ui_wgpu::wgpu::RasterTextureWitness { scene_revision, preview_generation, operation };
        *current = Some(witness);
        Ok(witness)
    }

    fn current(&self) -> Option<ui_wgpu::wgpu::RasterTextureWitness> {
        self.0.current.lock().ok().and_then(|current| *current)
    }

    fn matches(&self, witness: ui_wgpu::wgpu::RasterTextureWitness) -> bool {
        self.current() == Some(witness)
    }

    fn release(&self, witness: ui_wgpu::wgpu::RasterTextureWitness) -> Result<(), &'static str> {
        let mut current = self.0.current.lock().map_err(|_| "raster operation authority was poisoned")?;
        if *current != Some(witness) {
            return Err("raster operation authority was stale or duplicated");
        }
        *current = None;
        Ok(())
    }
}

#[cfg(not(target_arch = "wasm32"))]
type RuntimeHostWaker = Arc<dyn Fn() + Send + Sync>;

#[cfg(target_arch = "wasm32")]
type RuntimeHostWaker = std::rc::Rc<dyn Fn()>;

type RuntimeCompletion = runtime_mailbox_core::Completion<RuntimeApply>;
type RuntimeCompletionQueue = runtime_mailbox_core::BoundedCompletionQueue<RuntimeApply, RUNTIME_COMPLETION_CAPACITY>;

/// 📮️ A completion returned through a reservation the submitting turn already took: the revision was
/// minted when the work was submitted, it never needs the interaction state to apply, and whether it
/// CARRIES that state home is read off the apply itself — the one owner of that rule
/// ([`RuntimeApply::restores_interaction`]), so no call site can disagree with the checkout ledger.
fn returned_completion(revision: u64, apply: RuntimeApply) -> RuntimeCompletion {
    RuntimeCompletion { key: None, revision, requires_interaction: false, restores_interaction: apply.restores_interaction(), apply }
}

#[cfg(all(test, not(target_arch = "wasm32")))]
#[path = "../../../../../../../../🔨️modules/🖱️ui/🖥️host/📥️input/🎟️admission/🔗️commit/📥️enqueue/🧪️tests/📥️enqueue/🦀️.rs"]
mod runtime_publication_tests;

/// 📮️ Publishes one completion and its scene invalidation as ONE observation. The invalidation is
/// written while the mailbox lock is still held, so a reader that takes that lock can never see a
/// ready completion under the scene revision it was already built against.
///
/// 🐛️ ticket 26/09/17/WGPU-RENDERER-REACT-PARITY wave 2–6 integration: `mark_scene_changed` used to
/// run AFTER `drop(queue)`, and a reader landing in that window read `ready.len() == 1` beside the
/// OLD witness — a completion the frame it is about to present does not know it must rebuild for.
/// `mark_scene_changed` is a single `fetch_add` on an `AtomicU64`, so it adds no lock order.
fn enqueue_runtime_completion(completions: &Mutex<RuntimeCompletionQueue>, presentation: &RuntimePresentationAuthority, waker: &Mutex<Option<RuntimeHostWaker>>, completion: RuntimeCompletion) -> bool {
    let mut queue = completions.lock().expect("runtime completion mailbox lock");
    if !queue.enqueue(completion) {
        return false;
    }
    presentation.mark_scene_changed();
    drop(queue);
    #[cfg(all(test, not(target_arch = "wasm32")))]
    runtime_publication_tests::pause_after_completion_publication();
    if let Some(waker) = waker.lock().expect("runtime completion waker lock").as_ref() {
        waker();
    }
    true
}

#[cfg(not(all(target_arch = "wasm32", target_env = "p2")))]
enum StagedReferenceImage {
    Writing { token: WorldAssetRequestToken, url: String, descriptor: SceneRasterDescriptor, writer: SceneRasterWriter },
    Ready { token: WorldAssetRequestToken, url: String, lease: SceneRasterLease },
}

#[cfg(not(all(target_arch = "wasm32", target_env = "p2")))]
struct StagedReferenceImageAuthority {
    entries: std::collections::VecDeque<StagedReferenceImage>,
}

#[cfg(not(all(target_arch = "wasm32", target_env = "p2")))]
impl StagedReferenceImageAuthority {
    const BUSY: u8 = 0;
    const WRITER: u8 = 1;
    const REUSED: u8 = 2;

    fn new() -> Self {
        Self { entries: std::collections::VecDeque::with_capacity(4) }
    }

    fn begin(&mut self, pool: &SceneRasterPool, token: WorldAssetRequestToken, url: String, descriptor: SceneRasterDescriptor, owner: u64) -> Result<u8, &'static str> {
        if let Some(entry) = self.entries.iter().find(|entry| match entry {
            StagedReferenceImage::Writing { token: candidate, url: candidate_url, descriptor: candidate_descriptor, .. } => *candidate == token && candidate_url == &url && *candidate_descriptor == descriptor,
            StagedReferenceImage::Ready { token: candidate, url: candidate_url, lease } => *candidate == token && candidate_url == &url && lease.identity().descriptor() == descriptor,
        }) {
            return Ok(match entry {
                StagedReferenceImage::Writing { .. } => Self::BUSY,
                StagedReferenceImage::Ready { .. } => Self::REUSED,
            });
        }
        if self.entries.len() >= 4 {
            return Ok(Self::BUSY);
        }
        let (entry, mode) = match pool.begin(descriptor, owner, SceneRasterWriteMode::Streamed) {
            SceneRasterBegin::Writer(writer) => (StagedReferenceImage::Writing { token, url, descriptor, writer }, Self::WRITER),
            SceneRasterBegin::Reused(lease) => (StagedReferenceImage::Ready { token, url, lease }, Self::REUSED),
            SceneRasterBegin::Backpressure(_) => return Ok(Self::BUSY),
            SceneRasterBegin::Refused(fault) => return Err(fault),
        };
        self.entries.push_back(entry);
        Ok(mode)
    }

    fn push(&mut self, pool: &SceneRasterPool, token: WorldAssetRequestToken, offset: usize, bytes: &[u8]) -> Result<bool, &'static str> {
        let Some(entry) = self.entries.iter_mut().find(|entry| matches!(entry, StagedReferenceImage::Writing { token: candidate, .. } if *candidate == token)) else {
            return Ok(self.entries.iter().any(|entry| matches!(entry, StagedReferenceImage::Ready { token: candidate, .. } if *candidate == token)));
        };
        let StagedReferenceImage::Writing { writer, .. } = entry else { unreachable!("matched writing reference image") };
        if writer.cursor() != offset {
            return Err("reference image row cursor is stale");
        }
        *writer = pool.push(*writer, bytes)?;
        Ok(true)
    }

    fn seal(&mut self, pool: &SceneRasterPool, token: WorldAssetRequestToken) -> Result<bool, &'static str> {
        let Some(index) = self.entries.iter().position(|entry| matches!(entry, StagedReferenceImage::Writing { token: candidate, .. } if *candidate == token)) else {
            return Ok(self.entries.iter().any(|entry| matches!(entry, StagedReferenceImage::Ready { token: candidate, .. } if *candidate == token)));
        };
        let Some(StagedReferenceImage::Writing { token, url, writer, .. }) = self.entries.remove(index) else { unreachable!("located writing reference image") };
        match pool.seal(writer) {
            Ok(lease) => {
                self.entries.push_back(StagedReferenceImage::Ready { token, url, lease });
                Ok(true)
            }
            Err(fault) => {
                let _ = pool.cancel(writer);
                Err(fault)
            }
        }
    }

    fn take(&mut self, token: WorldAssetRequestToken, url: &str) -> Option<SceneRasterLease> {
        let index = self.entries.iter().position(|entry| matches!(entry, StagedReferenceImage::Ready { token: candidate, url: candidate_url, .. } if *candidate == token && candidate_url == url))?;
        let Some(StagedReferenceImage::Ready { lease, .. }) = self.entries.remove(index) else { unreachable!("located ready reference image") };
        Some(lease)
    }

    fn restore(&mut self, token: WorldAssetRequestToken, url: String, lease: SceneRasterLease) {
        assert!(self.entries.len() < 4, "a just-taken reference raster restores into its exact stage slot");
        self.entries.push_back(StagedReferenceImage::Ready { token, url, lease });
    }

    fn discard(&mut self, pool: &SceneRasterPool, token: WorldAssetRequestToken) {
        let Some(index) = self.entries.iter().position(|entry| match entry {
            StagedReferenceImage::Writing { token: candidate, .. } | StagedReferenceImage::Ready { token: candidate, .. } => *candidate == token,
        }) else {
            return;
        };
        if let Some(StagedReferenceImage::Writing { writer, .. }) = self.entries.remove(index) {
            let _ = pool.cancel(writer);
        }
    }
}

#[cfg(not(target_arch = "wasm32"))]
enum NativeReferenceDecodeOutput {
    Ready(SceneRasterLease),
    Waiting(DecodedReferenceImage),
    Failed,
}

#[cfg(not(target_arch = "wasm32"))]
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum NativeReferenceDecodeCloseStep {
    Busy,
    Pending { released_items: usize, released_bytes: usize },
    Complete,
}

#[cfg(not(target_arch = "wasm32"))]
struct NativeReferenceDecodeJob {
    token: WorldAssetRequestToken,
    url: String,
    input: Mutex<Option<Vec<u8>>>,
    decoded: Mutex<Option<DecodedReferenceImage>>,
    output: Mutex<Option<NativeReferenceDecodeOutput>>,
    phase: std::sync::atomic::AtomicU8,
    cancelled: AtomicBool,
    #[cfg(test)]
    worker_barriers: Mutex<Option<(Arc<std::sync::Barrier>, Arc<std::sync::Barrier>)>>,
}

#[cfg(not(target_arch = "wasm32"))]
impl NativeReferenceDecodeJob {
    fn new(token: WorldAssetRequestToken, url: String, bytes: Vec<u8>) -> Self {
        Self {
            token,
            url,
            input: Mutex::new(Some(bytes)),
            decoded: Mutex::new(None),
            output: Mutex::new(None),
            phase: std::sync::atomic::AtomicU8::new(0),
            cancelled: AtomicBool::new(false),
            #[cfg(test)]
            worker_barriers: Mutex::new(None),
        }
    }

    fn try_schedule(self: &Arc<Self>, mailbox: RuntimeMailbox) -> bool {
        if self.phase.compare_exchange(0, 1, Ordering::AcqRel, Ordering::Acquire).is_err() {
            return false;
        }
        let scheduled = self.clone();
        let pool = mailbox.0.scene_raster_pool.clone();
        let job: semio_framework_async::Job =
            Box::new(move || {
                let bytes = scheduled.input.lock().unwrap_or_else(|poisoned| poisoned.into_inner()).take();
                let decoded = scheduled.decoded.lock().unwrap_or_else(|poisoned| poisoned.into_inner()).take().or_else(|| {
                    if scheduled.cancelled.load(Ordering::Acquire) {
                        None
                    } else {
                        bytes.as_deref().and_then(infinite_world::world::decode_reference_image_bytes)
                    }
                });
                #[cfg(test)]
                if let Some((entered, release)) = scheduled.worker_barriers.lock().unwrap_or_else(|poisoned| poisoned.into_inner()).as_ref().cloned() {
                    entered.wait();
                    release.wait();
                }
                let mut retained_decoded = None;
                let output = if scheduled.cancelled.load(Ordering::Acquire) {
                    retained_decoded = decoded;
                    NativeReferenceDecodeOutput::Failed
                } else if let Some(decoded) = decoded {
                    let descriptor = SceneRasterDescriptor { width: decoded.width, height: decoded.height, source_digest: decoded.source_digest, source_revision: 1, profile: SceneRasterProfile::ReferenceImageMapNoColorSpace, mesh: None };
                    let owner = decoded.source_digest[0].wrapping_add(decoded.source_digest[1]).max(1);
                    match pool.begin(descriptor, owner, SceneRasterWriteMode::Moved) {
                        SceneRasterBegin::Reused(lease) => {
                            retained_decoded = Some(decoded);
                            NativeReferenceDecodeOutput::Ready(lease)
                        }
                        SceneRasterBegin::Writer(writer) => {
                            let DecodedReferenceImage { width, height, source_digest, pixels } = decoded;
                            match pool.prepare_moved(writer, pixels).and_then(|prepared| pool.seal_prepared_moved(prepared)) {
                                Ok(lease) => NativeReferenceDecodeOutput::Ready(lease),
                                Err((pixels, _fault)) => {
                                    let _ = pool.cancel(writer);
                                    retained_decoded = Some(DecodedReferenceImage { width, height, source_digest, pixels });
                                    NativeReferenceDecodeOutput::Failed
                                }
                            }
                        }
                        SceneRasterBegin::Backpressure(_) => NativeReferenceDecodeOutput::Waiting(decoded),
                        SceneRasterBegin::Refused(_) => {
                            retained_decoded = Some(decoded);
                            NativeReferenceDecodeOutput::Failed
                        }
                    }
                } else {
                    NativeReferenceDecodeOutput::Failed
                };
                if let Some(bytes) = bytes {
                    let mut retained = scheduled.input.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
                    assert!(retained.is_none(), "the native reference worker returns one exact encoded owner");
                    *retained = Some(bytes);
                }
                if let Some(decoded) = retained_decoded {
                    let mut retained = scheduled.decoded.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
                    assert!(retained.is_none(), "the native reference worker returns one exact decoded owner");
                    *retained = Some(decoded);
                }
                *scheduled.output.lock().unwrap_or_else(|poisoned| poisoned.into_inner()) = Some(output);
                scheduled.phase.store(if scheduled.cancelled.load(Ordering::Acquire) { 3 } else { 6 }, Ordering::Release);
                if let Some(waker) = mailbox.0.waker.lock().expect("runtime completion waker lock").as_ref() {
                    waker();
                }
            });
        match renderer_worker_pool().try_submit(semio_framework_async::Lane::Maintenance, job) {
            Ok(()) => true,
            Err(error) => {
                drop(error.into_job());
                self.phase.store(if self.cancelled.load(Ordering::Acquire) { 3 } else { 0 }, Ordering::Release);
                false
            }
        }
    }

    fn cancel(&self) {
        self.cancelled.store(true, Ordering::Release);
        loop {
            let phase = self.phase.load(Ordering::Acquire);
            if !matches!(phase, 0 | 2 | 6) {
                break;
            }
            if self.phase.compare_exchange(phase, 3, Ordering::AcqRel, Ordering::Acquire).is_ok() {
                break;
            }
        }
    }

    fn take_output(&self) -> Option<NativeReferenceDecodeOutput> {
        if self.phase.compare_exchange(2, 5, Ordering::AcqRel, Ordering::Acquire).is_err() {
            return None;
        }
        self.output.lock().unwrap_or_else(|poisoned| poisoned.into_inner()).take()
    }

    fn rearm(&self, decoded: DecodedReferenceImage) -> bool {
        *self.decoded.lock().unwrap_or_else(|poisoned| poisoned.into_inner()) = Some(decoded);
        let ready = !self.cancelled.load(Ordering::Acquire);
        self.phase.store(if ready { 0 } else { 3 }, Ordering::Release);
        ready
    }

    fn restore_output(&self, output: NativeReferenceDecodeOutput) {
        *self.output.lock().unwrap_or_else(|poisoned| poisoned.into_inner()) = Some(output);
        self.phase.store(if self.cancelled.load(Ordering::Acquire) { 3 } else { 2 }, Ordering::Release);
    }

    fn retire_payload_step(&self, maximum_items: usize, maximum_bytes: usize) -> NativeReferenceDecodeCloseStep {
        if maximum_items == 0 {
            return NativeReferenceDecodeCloseStep::Pending { released_items: 0, released_bytes: 0 };
        }
        {
            let mut decoded = self.decoded.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
            if let Some(image) = decoded.as_mut() {
                if !image.pixels.is_empty() {
                    let released_bytes = image.pixels.len().min(maximum_bytes);
                    if released_bytes == 0 {
                        return NativeReferenceDecodeCloseStep::Pending { released_items: 0, released_bytes: 0 };
                    }
                    image.pixels.truncate(image.pixels.len() - released_bytes);
                    return NativeReferenceDecodeCloseStep::Pending { released_items: 0, released_bytes };
                }
                *decoded = None;
                return NativeReferenceDecodeCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
        }
        {
            let mut input = self.input.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
            if let Some(bytes) = input.as_mut() {
                if !bytes.is_empty() {
                    let released_bytes = bytes.len().min(maximum_bytes);
                    if released_bytes == 0 {
                        return NativeReferenceDecodeCloseStep::Pending { released_items: 0, released_bytes: 0 };
                    }
                    bytes.truncate(bytes.len() - released_bytes);
                    return NativeReferenceDecodeCloseStep::Pending { released_items: 0, released_bytes };
                }
                *input = None;
                return NativeReferenceDecodeCloseStep::Pending { released_items: 1, released_bytes: 0 };
            }
        }
        NativeReferenceDecodeCloseStep::Complete
    }

    fn close_step(&self, maximum_items: usize, maximum_bytes: usize) -> NativeReferenceDecodeCloseStep {
        self.cancel();
        match self.phase.load(Ordering::Acquire) {
            1 | 5 => return NativeReferenceDecodeCloseStep::Busy,
            4 => return NativeReferenceDecodeCloseStep::Complete,
            0 | 2 => return NativeReferenceDecodeCloseStep::Busy,
            3 => {}
            _ => return NativeReferenceDecodeCloseStep::Busy,
        }
        if maximum_items == 0 {
            return NativeReferenceDecodeCloseStep::Pending { released_items: 0, released_bytes: 0 };
        }
        if let Some(output) = self.output.lock().unwrap_or_else(|poisoned| poisoned.into_inner()).take() {
            match output {
                NativeReferenceDecodeOutput::Waiting(decoded) => {
                    let mut retained = self.decoded.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
                    assert!(retained.is_none(), "one native reference decode owns at most one decoded image");
                    *retained = Some(decoded);
                    return NativeReferenceDecodeCloseStep::Pending { released_items: 0, released_bytes: 0 };
                }
                NativeReferenceDecodeOutput::Ready(lease) => {
                    let _ = lease.release();
                }
                NativeReferenceDecodeOutput::Failed => {}
            }
            return NativeReferenceDecodeCloseStep::Pending { released_items: 1, released_bytes: 0 };
        }
        let step = self.retire_payload_step(maximum_items, maximum_bytes);
        if !matches!(step, NativeReferenceDecodeCloseStep::Complete) {
            return step;
        }
        self.phase.store(4, Ordering::Release);
        NativeReferenceDecodeCloseStep::Complete
    }
}

