    }

    pub(crate) fn record_frame_fault(&self, fault: &'static str) {
        log_debug(&format!("[TRACE] frame fault recorded: {fault}"));
        let mut slot = self.0.frame_fault.lock().expect("runtime frame fault lock");
        if slot.is_none() {
            *slot = Some(fault.to_string());
        }
    }

