    raster_operation_authority: RuntimeRasterOperationAuthority,
    window: Option<Arc<Window>>,
    #[cfg(target_arch = "wasm32")]
    offscreen_token: Option<ui_wgpu::wgpu::OffscreenPresentToken>,
