    message: std::mem::ManuallyDrop<Option<crate::os_spr::MutationMessage>>,
    envelope: std::mem::ManuallyDrop<Option<crate::os_spr::MutationEnvelope>>,
    bytes: std::mem::ManuallyDrop<Option<Vec<u8>>>,
