    fn preflight(&self, wire: &MemberStoreOneItemWire, description: Option<&str>, lane: HistoryLane) -> Result<ArtifactStoreOneItemFootprint, String>;
    fn begin(&self, request: ArtifactStoreOneItemPreparationRequest<P, MemberStoreOneItemWire>) -> Result<Box<dyn ArtifactStoreOneItemPreparation<P, Mutation>>, ArtifactStoreOneItemPreparationRequest<P, MemberStoreOneItemWire>>;
}

/// 🪪 Erased retained publication; only its exact member may advance the typed candidate.
pub trait ErasedMemberStoreOneItemPublication: Send {
    fn as_any_mut(&mut self) -> &mut dyn std::any::Any;
    fn phase(&self) -> ArtifactStoreOneItemPublicationPhase;
    fn progress(&self) -> ArtifactStoreOneItemCheckpoint;
    fn fault(&self) -> Option<&str>;
    fn retry(&mut self) -> bool;
    fn acknowledge(&mut self) -> bool;
    fn begin_close(&mut self);
    fn close_step(&mut self, grant: ArtifactStoreOneItemGrant) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError>;
    fn terminal_is_empty(&self) -> bool;
}

struct MemberStoreOneItemPublication<P, Mutation> {
    member: Option<Arc<SnapshotReadLeaseRegistry>>,
    publication: ArtifactStoreBatchPublication<P, Mutation>,
    group_history: Option<ArtifactStoreHistoryCommitReservation>,
    group_displaced: Option<ArtifactStoreDisplacedOwnerReservation>,
}

impl<P: Send + Sync + 'static, Mutation: Send + 'static> ErasedMemberStoreOneItemPublication for MemberStoreOneItemPublication<P, Mutation> {
    fn as_any_mut(&mut self) -> &mut dyn std::any::Any {
        self
    }

    fn phase(&self) -> ArtifactStoreOneItemPublicationPhase {
        self.publication.phase()
    }

    fn progress(&self) -> ArtifactStoreOneItemCheckpoint {
        self.publication.progress()
    }

    fn fault(&self) -> Option<&str> {
        self.publication.fault()
    }

    fn retry(&mut self) -> bool {
        self.publication.retry()
    }

    fn acknowledge(&mut self) -> bool {
        self.publication.acknowledge()
    }

    fn begin_close(&mut self) {
        self.publication.begin_close();
    }

    fn close_step(&mut self, grant: ArtifactStoreOneItemGrant) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError> {
        if self.group_history.is_some() || self.group_displaced.is_some() {
            return Ok(SnapshotRetirementStep::Blocked);
        }
        if !self.publication.terminal_is_empty() {
            return self.publication.close_step(grant).map(|step| if step == SnapshotRetirementStep::Complete { SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 } } else { step });
        }
        if grant.maximum_items == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if self.member.take().is_some() {
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        Ok(SnapshotRetirementStep::Complete)
    }

    fn terminal_is_empty(&self) -> bool {
        self.member.is_none() && self.publication.terminal_is_empty() && self.group_history.is_none() && self.group_displaced.is_none()
    }
}

impl<P, Mutation> Drop for MemberStoreOneItemPublication<P, Mutation> {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.member.is_none() && self.publication.terminal_is_empty() && self.group_history.is_none() && self.group_displaced.is_none()), "member publication reached Drop before exact member, reservation, and candidate retirement");
    }
}
//#endregion 🧩️MemberOneItemPublication

/// 🔄 Persistent store-side operation phases. Publication and ACK are distinct turns; close
/// remains observable until the domain owner proves exact terminal emptiness.
#[derive(Clone, Copy, Debug, PartialEq, Eq, ToValue, FromValue)]
#[value(rename_all = "camelCase")]
pub enum ArtifactStoreOneItemPublicationPhase {
    Preparing,
    PreparingCursor,
    PreflightingCommit,
    Publishing,
    AwaitingAck,
    Closing,
    Complete,
    Fault,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ArtifactStoreOneItemAdvance {
    Progress(ArtifactStoreOneItemCheckpoint),
    Published(LaneItemReceipt),
    AwaitingAck(LaneItemReceipt),
    Complete,
    Blocked,
}

/// 🚫 Exact owners returned when the app has no retained factory, preflight rejects, or the
/// store's live base authority no longer matches. The whole admitted gesture comes back in the
/// order it was offered, so the caller can retry or retire it without reconstructing anything.
#[derive(Debug)]
pub struct ArtifactStoreBatchAdmissionRejected<Mutation> {
    pub reason: String,
    pub mutations: Vec<Mutation>,
    pub description: Option<String>,
}

impl<Mutation> ArtifactStoreBatchAdmissionRejected<Mutation> {
    pub fn into_owners(self) -> (String, Vec<Mutation>, Option<String>) {
        (self.reason, self.mutations, self.description)
    }
}

/// 🧾️ One gesture's staged edit. Every admitted mutation is folded into these exact owners against
/// the running post root, so the whole gesture commits as ONE `Edit` in ONE history ledger slot and
/// is ONE undo step. It carries its own retirement authority: a cancelled batch retires the staged
/// forwards, inverses, metadata and post root one owner per bounded turn.
struct ArtifactStoreBatchStage<P, Mutation> {
    edit: Box<Edit<Mutation>>,
    post: Option<Arc<P>>,
    next_clock: HybridLogicalTimestamp,
    local_actor: Option<String>,
    applied_edit_id: String,
    tail_edit_id: String,
    digest: [u8; 32],
    folded: usize,
    completed_items: u32,
    completed_bytes: u64,
    mutation_retirement: Option<Arc<dyn ArtifactOwnedValueRetirementFactory<Mutation>>>,
    snapshot_retirement: Option<Arc<dyn SnapshotRetirementFactory<P>>>,
    retiring: Option<Box<dyn ErasedSnapshotRetirement>>,
}

impl<P, Mutation> ArtifactStoreBatchStage<P, Mutation> {
    fn checkpoint(&self) -> ArtifactStoreOneItemCheckpoint {
        ArtifactStoreOneItemCheckpoint { cursor: self.folded as u32, completed_items: self.completed_items, completed_bytes: self.completed_bytes, digest: self.digest }
    }

    fn close_step(&mut self, grant: ArtifactStoreOneItemGrant) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError> {
        if let Some(owner) = self.retiring.as_mut() {
            let step = owner.close_step(grant.maximum_items.min(1), grant.maximum_bytes)?;
            if step != SnapshotRetirementStep::Complete {
                return Ok(step);
            }
            if !owner.terminal_is_empty() {
                return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "staged batch owner retirement reported complete without terminal emptiness"));
            }
            self.retiring = None;
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if grant.maximum_items == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if let Some(value) = self.edit.inverse.pop().or_else(|| self.edit.forwards.pop()) {
            let factory = self.mutation_retirement.as_ref().ok_or_else(|| semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "staged batch edit lacks its exact mutation retirement authority"))?;
            self.retiring = Some(factory.retire_owned(value));
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if self.edit.mutation_meta.pop().is_some() {
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if let Some(post) = self.post.take() {
            let factory = self.snapshot_retirement.as_ref().ok_or_else(|| semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "staged batch root lacks its exact snapshot retirement authority"))?;
            self.retiring = Some(factory.retire(post));
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        for value in [&mut self.edit.id, &mut self.applied_edit_id, &mut self.tail_edit_id, &mut self.edit.started_at] {
            if !value.is_empty() {
                let released = value.len();
                value.clear();
                value.shrink_to_fit();
                return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: released });
            }
        }
        for value in [&mut self.edit.actor, &mut self.edit.line, &mut self.edit.description, &mut self.edit.verb, &mut self.edit.finished_at, &mut self.local_actor] {
            if let Some(taken) = value.take() {
                return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: taken.len() });
            }
        }
        if self.mutation_retirement.take().is_some() || self.snapshot_retirement.take().is_some() {
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        Ok(SnapshotRetirementStep::Complete)
    }

    fn terminal_is_empty(&self) -> bool {
        self.retiring.is_none()
            && self.post.is_none()
            && self.edit.forwards.is_empty()
            && self.edit.inverse.is_empty()
            && self.edit.mutation_meta.is_empty()
            && self.edit.id.is_empty()
            && self.applied_edit_id.is_empty()
            && self.tail_edit_id.is_empty()
            && self.edit.started_at.is_empty()
            && self.edit.actor.is_none()
            && self.edit.line.is_none()
            && self.edit.description.is_none()
            && self.edit.verb.is_none()
            && self.edit.finished_at.is_none()
            && self.local_actor.is_none()
            && self.mutation_retirement.is_none()
            && self.snapshot_retirement.is_none()
    }
}

/// 📬️ Retained batched publication authority: ONE user gesture, N admitted mutations, ONE staged
/// `Edit`, ONE history ledger slot, ONE undo step. Each turn folds at most one mutation — the
/// single-mutation case is simply the N = 1 batch. It never calls `apply_one`, `apply_command`,
/// `replay_mutations`, `pump`, or `flush_outbound`.
pub struct ArtifactStoreBatchPublication<P, Mutation> {
    operation: semio_framework_job::OperationId,
    expected_generation: u64,
    expected_revision: [u8; 32],
    lane: HistoryLane,
    footprint: ArtifactStoreOneItemFootprint,
    admitted_items: usize,
    authority: Option<Arc<ArtifactStoreOneItemLiveAuthority>>,
    authority_retirement: Option<Box<dyn ErasedSnapshotRetirement>>,
    source: Option<Box<dyn ArtifactStoreBatchSource<P, Mutation>>>,
    preparation: Option<Box<dyn ArtifactStoreOneItemPreparation<P, Mutation>>>,
    item_closing: bool,
    stage: Option<Box<ArtifactStoreBatchStage<P, Mutation>>>,
    retained_checkpoint: ArtifactStoreOneItemCheckpoint,
    receipt: Option<LaneItemReceipt>,
    attempts: u8,
    published: bool,
    cancel_requested: bool,
    close_started: bool,
    fault: Option<String>,
    phase: ArtifactStoreOneItemPublicationPhase,
    verb: Option<String>,
    transaction: Option<protocol::TransactionRef>,
    outbound: bool,
    announce_from: usize,
    announce_items: usize,
    transaction_open: bool,
}

impl<P, Mutation> ArtifactStoreBatchPublication<P, Mutation> {
    pub fn operation(&self) -> semio_framework_job::OperationId {
        self.operation
    }

    pub fn phase(&self) -> ArtifactStoreOneItemPublicationPhase {
        self.phase
    }

    /// 🏷️ The id of the action or command this gesture publishes for, stamped on the gesture's new edit (an amend keeps
    /// the verb of the edit it extends). See [`crate::os_spr::command::Edit::verb`].
    pub fn set_verb(&mut self, verb: Option<String>) {
        self.verb = verb.filter(|value| !value.is_empty());
    }

    /// 🧾️ The committed tool transaction this gesture publishes for, stamped on every staged operation.
    pub fn transaction(&self) -> Option<&protocol::TransactionRef> {
        self.transaction.as_ref()
    }

    /// 🫙️ Keeps this gesture's tool transaction open after its operations land: they join the transaction's open edit (the
    /// first streamed gesture opens it) and nothing is announced until a closing gesture or `CommitTransaction` commits
    /// it. A closing gesture (the default) that carries the open transaction's ref appends to its edit and commits it.
    pub fn set_transaction_open(&mut self, open: bool) {
        self.transaction_open = open;
    }

    /// 🔢️ How many mutations this gesture admitted, and how many of them are already staged.
    pub fn admitted_items(&self) -> usize {
        self.admitted_items
    }

    pub fn staged_items(&self) -> usize {
        self.stage.as_ref().map_or(0, |stage| stage.folded)
    }

    /// 🎁️ Hands the staged gesture edit back as ONE sealed candidate so a group-atomic decision can
    /// linearize several stores' candidates before any of them becomes visible. Only the commit turn
    /// may call it, and the publication then owns nothing but its receipt lane.
    fn take_staged_prepared(&mut self) -> Option<ArtifactStoreOneItemPrepared<P, Mutation>> {
        if self.phase != ArtifactStoreOneItemPublicationPhase::Publishing || self.stage.as_ref().is_none_or(|stage| stage.post.is_none()) {
            return None;
        }
        let authority = Arc::clone(self.authority.as_ref()?);
        let stage = self.take_stage()?;
        let ArtifactStoreBatchStage { edit, post, local_actor: _, applied_edit_id, tail_edit_id, digest, .. } = *stage;
        let post = post.expect("validated staged batch post root");
        Some(authority.seal_prepared_owned(edit, post, digest, [authority.actor.clone(), applied_edit_id, tail_edit_id]))
    }

    fn take_stage(&mut self) -> Option<Box<ArtifactStoreBatchStage<P, Mutation>>> {
        let stage = self.stage.take()?;
        self.retained_checkpoint = stage.checkpoint();
        Some(stage)
    }

    /// 📍️ Gesture-wide progress survives folding, publication, acknowledgement, and owner retirement.
    pub fn progress(&self) -> ArtifactStoreOneItemCheckpoint {
        if self.close_started { return self.retained_checkpoint; }
        let staged = self.stage.as_ref().map_or(self.retained_checkpoint, |stage| stage.checkpoint());
        let item = if self.item_closing { ArtifactStoreOneItemCheckpoint::default() } else { self.preparation.as_ref().map_or_else(ArtifactStoreOneItemCheckpoint::default, |owner| owner.checkpoint()) };
        ArtifactStoreOneItemCheckpoint {
            cursor: staged.cursor,
            completed_items: staged.completed_items.saturating_add(item.completed_items),
            completed_bytes: staged.completed_bytes.saturating_add(item.completed_bytes),
            digest: if item.digest == [0; 32] { staged.digest } else { item.digest },
        }
    }

    pub fn fault(&self) -> Option<&str> {
        self.fault.as_deref()
    }

    pub fn retry(&mut self) -> bool {
        if self.phase != ArtifactStoreOneItemPublicationPhase::AwaitingAck || self.attempts >= ARTIFACT_STORE_ONE_ITEM_MAXIMUM_RETRIES {
            return false;
        }
        self.attempts += 1;
        true
    }

    pub fn acknowledge(&mut self) -> bool {
        if self.phase != ArtifactStoreOneItemPublicationPhase::AwaitingAck || self.outbound {
            return false;
        }
        self.phase = ArtifactStoreOneItemPublicationPhase::Closing;
        self.begin_close();
        true
    }

    pub fn begin_close(&mut self) {
        if self.close_started {
            return;
        }
        self.retained_checkpoint = self.progress();
        self.close_started = true;
        self.phase = if self.phase == ArtifactStoreOneItemPublicationPhase::Complete { ArtifactStoreOneItemPublicationPhase::Complete } else { ArtifactStoreOneItemPublicationPhase::Closing };
        if let Some(owner) = self.preparation.as_mut() {
            if !self.published {
                self.cancel_requested = true;
                owner.cancel();
            }
            owner.begin_close();
        }
    }

    pub fn close_step(&mut self, grant: ArtifactStoreOneItemGrant) -> Result<SnapshotRetirementStep, semio_framework_value::ValueError>
    where
        P: Send + Sync + 'static,
    {
        self.begin_close();
        if let Some(owner) = self.preparation.as_mut() {
            let step = owner.close_step(ArtifactStoreOneItemGrant { maximum_items: grant.maximum_items.min(1), maximum_bytes: grant.maximum_bytes })?;
            if step != SnapshotRetirementStep::Complete {
                return Ok(step);
            }
            if !owner.terminal_is_empty() {
                return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "one-item preparation reported complete without terminal emptiness"));
            }
            self.preparation = None;
            self.item_closing = false;
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if let Some(source) = self.source.as_mut() {
            let step = source.close_step(ArtifactStoreOneItemGrant { maximum_items: grant.maximum_items.min(1), maximum_bytes: grant.maximum_bytes });
            if step != SnapshotRetirementStep::Complete {
                return Ok(step);
            }
            if !source.terminal_is_empty() {
                return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "batch source reported complete without terminal emptiness"));
            }
            self.source = None;
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if let Some(stage) = self.stage.as_mut() {
            let step = stage.close_step(grant)?;
            if step != SnapshotRetirementStep::Complete {
                return Ok(step);
            }
            if !stage.terminal_is_empty() {
                return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "staged batch edit reported complete without terminal emptiness"));
            }
            self.stage = None;
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if grant.maximum_items == 0 {
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
        }
        if self.verb.take().is_some() {
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if self.receipt.take().is_some() {
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if let Some(owner) = self.authority_retirement.as_mut() {
            let step = owner.close_step(1, grant.maximum_bytes)?;
            if step != SnapshotRetirementStep::Complete { return Ok(step); }
            if !owner.terminal_is_empty() { return Err(semio_framework_value::ValueError::new(semio_framework_value::ValueRefusalKind::InvariantViolated, "batch authority reported complete without terminal emptiness")); }
            self.authority_retirement = None;
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if let Some(authority) = self.authority.take() {
            self.authority_retirement = Some(authority.retire());
            return Ok(SnapshotRetirementStep::Pending { released_items: 1, released_bytes: 0 });
        }
        if let Some(fault) = self.fault.as_mut().filter(|fault| !fault.is_empty()) {
            let scalar = fault.chars().next_back().expect("nonempty batch fault");
            if scalar.len_utf8() > grant.maximum_bytes {
                return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: 0 });
            }
            fault.pop();
            return Ok(SnapshotRetirementStep::Pending { released_items: 0, released_bytes: scalar.len_utf8() });
        }
        self.fault = None;
        self.phase = ArtifactStoreOneItemPublicationPhase::Complete;
        Ok(SnapshotRetirementStep::Complete)
    }

    pub fn terminal_is_empty(&self) -> bool {
        self.phase == ArtifactStoreOneItemPublicationPhase::Complete && self.preparation.is_none() && self.source.is_none() && self.stage.is_none() && self.authority.is_none() && self.authority_retirement.is_none() && self.receipt.is_none() && self.fault.is_none() && self.verb.is_none()
    }

    /// 🔬️ The first owner `close_step` would try to retire, in its exact drain order, plus whether
    /// `begin_close` has run. `close_step` answers only `Pending`/`Blocked`/`Complete`, so a
    /// publication that will not reach terminal emptiness under repeated one-item grants cannot say
    /// WHICH of its seven owners refuses. This names it.
    pub fn closing_owner_witness(&self) -> &'static str {
        if !self.close_started {
            return "close-not-started";
        }
        if self.preparation.is_some() {
            "preparation"
        } else if self.source.is_some() {
            "source"
        } else if self.stage.is_some() {
            "stage"
        } else if self.verb.is_some() {
            "verb"
        } else if self.receipt.is_some() {
            "receipt"
        } else if self.authority_retirement.is_some() {
            "authority-retirement"
        } else if self.authority.is_some() {
            "authority"
        } else if self.fault.is_some() {
            "fault"
        } else {
            "none"
        }
    }
}

impl<P, Mutation> Drop for ArtifactStoreBatchPublication<P, Mutation> {
    fn drop(&mut self) {
        assert!(std::thread::panicking() || (self.terminal_is_empty()), "batched artifact-store publication reached Drop without its exact terminal-empty witness");
    }
}
//#endregion 📬️OneItemPublication

pub struct ArtifactStore<P, Mutation>
where
    P: Clone + ToValue + FromValue,
    Mutation: Clone + ToValue + FromValue + self::Mutation<P>,
{
    envelope: std::mem::ManuallyDrop<ArtifactEnvelope<P, Mutation>>,
    envelope_detached: bool,
    backbone: std::mem::ManuallyDrop<Option<Backbones>>,
    dag: std::mem::ManuallyDrop<crate::os_spr::MutationDag>,
    applied_edit_ids: std::mem::ManuallyDrop<crate::os_vcs::HistoryPageStack<String>>,
    redo_edit_ids: std::mem::ManuallyDrop<crate::os_vcs::HistoryPageStack<String>>,
    edit_sequence: i32,
    generation: u64,
    last_projection_cause: Option<ArtifactProjectionCause>,
    /// 🧭️ The checkpoint new commits parent onto; advances on commit/checkout/switch. Not
    /// part of the wire envelope — callers that reconstruct the store per call (e.g. a WASM plugin)
    /// must save/restore it themselves via {@link current_checkpoint_id}/{@link set_current_checkpoint_id}.
    current_checkpoint_id: std::mem::ManuallyDrop<Option<String>>,
    /// 🖋️ Identity of the local actor driving this store. Set from each local `Apply`/
    /// `Apply`'s operation author; compared against `Edit.actor` so undo never touches foreign
    /// edits. Not part of the wire envelope — callers that reconstruct the store per call must
    /// save/restore it via {@link local_actor_id}/{@link set_local_actor_id}.
    local_actor_id: std::mem::ManuallyDrop<Option<String>>,
    /// ⚖️ This store's local `crate::os_spr::MergePolicy` — authority-local state, defaults
    /// to `Normal`, never carried on the wire envelope (never part of an artifact's shared history).
    merge_policy: crate::os_spr::MergePolicy,
    /// ⏰️ Monotone hybrid logical clock: `tick`s on every local apply, `merge`s in a remote
    /// tick on every ingest — replaces the old per-call `HybridLogicalTimestamp::new(0, now_ms())`
    /// construction in `replay_mutations`. Not part of the wire envelope.
    clock: HybridLogicalTimestamp,
    /// 🧬️ Stable identity of the immutable genesis content, computed once on load/reset rather
    /// than by a composing app's action dispatch.
    initial_digest: [u8; 32],
    /// 🧬️ Fixed cursor digest refreshed at mutation boundaries and cloned by composition reads.
    content_revision: [u8; 32],
    /// 🧬️ Prefix-authenticated applied/redo cursor state. Tail mutations update one record;
    /// load/reset and the already-cold interior-history paths rebuild only their changed suffix.
    revision_accumulator: std::mem::ManuallyDrop<CursorRevisionAccumulator>,
    /// ⚡️ The live, incrementally-maintained RAW fold of `initial_snapshot` over every
    /// `forwards` operation in `applied_edit_ids` order — i.e. exactly what a full
    /// {@link materialize_document_snapshot} replay computes BEFORE its single final
    /// {@link Mutation::reconcile} call. Kept in lock-step by every mutating command below instead of
    /// replaying on every read, so `snapshot()`/`Apply`/`AppendTransaction` are O(new work) instead of
    /// O(total history). Cold-path commands (checkout/switch/set_state, which reassign
    /// `applied_edit_ids` wholesale rather than appending) fall back to a full raw-fold recompute —
    /// see `fold_current`. Differential ground truth: `test_support::assert_live_equals_replay`.
    current: std::mem::ManuallyDrop<Arc<P>>,
    current_detached: bool,
    /// 🪢️ `(edit_id, snapshot right before that edit's forwards were first applied)` for
    /// whichever edit is CURRENTLY the tail of `applied_edit_ids` — refreshed by `Apply`/`AppendTransaction`
    /// (fresh-edit branch)/`Redo`, left untouched by further amends to the same edit (so it always
    /// points at the state before the edit as a whole, not before its latest increment). Powers an
    /// O(1) `Undo` of exactly this edit; any other undo (not the cached tail, or `None`) falls back
    /// to `fold_current` — always correct, just not always O(1).
    tail_undo_cache: std::mem::ManuallyDrop<Option<(String, Arc<P>)>>,
    /// ✏️ The effective supersessions `current` was projected with ([`crate::os_spr::HistoryFold::supersessions`]) —
    /// what {@link reproject} compares a fresh fold against to find the first position whose effective input changed.
    supersessions: std::mem::ManuallyDrop<EffectiveSupersessions>,
    /// 🧭️ Retained projections after applied prefixes ([`PrefixSnapshot`]), at most [`PREFIX_SNAPSHOT_RING_CAPACITY`]
    /// at an adaptive stride: "the state before operation X" costs at most one stride of folds. An entry is valid only
    /// while its forwards-only digest names the live effective prefix; every evicted entry retires through the snapshot
    /// retirement factory (or only drops its alias while another owner holds the root), never a bare drop.
    prefix_ring: std::mem::ManuallyDrop<Vec<PrefixSnapshot<P>>>,
    /// 📍️ The first applied position whose revision record a replay rewrote (effective input, inverse or messages);
    /// the next {@link bump} rebuilds the cursor revision from there.
    revision_dirty_from: Option<usize>,
    /// 🟰️ Snapshot equality that lets a Report replay stop where it meets the previous projection
    /// ({@link enable_convergence_early_exit}).
    snapshot_equality: Option<fn(&P, &P) -> bool>,
    /// ♻️ Exact domain-owned bounded disposer for immutable snapshot roots transferred out
    /// of this store. Composition retirement fails closed until the owner installs it.
    snapshot_retirement_factory: std::mem::ManuallyDrop<Option<Arc<dyn SnapshotRetirementFactory<P>>>>,
    initial_snapshot_retirement_factory: std::mem::ManuallyDrop<Option<Arc<dyn ArtifactOwnedValueRetirementFactory<P>>>>,
    mutation_retirement_factory: std::mem::ManuallyDrop<Option<Arc<dyn ArtifactOwnedValueRetirementFactory<Mutation>>>>,
    snapshot_read_leases: std::mem::ManuallyDrop<Arc<SnapshotReadLeaseRegistry>>,
    displaced_retirements: std::mem::ManuallyDrop<ArtifactStoreDisplacedRetirements>,
    owned_disposer: std::mem::ManuallyDrop<Option<Box<dyn ArtifactStoreOwnedDisposer<P, Mutation>>>>,
    owned_disposer_terminal: bool,
    one_item_preparation_factory: std::mem::ManuallyDrop<Option<Arc<dyn ArtifactStoreOneItemPreparationFactory<P, Mutation>>>>,
    one_item_wire_preparation_factory: std::mem::ManuallyDrop<Option<Arc<dyn MemberStoreOneItemWirePreparationFactory<P, Mutation>>>>,
    /// 📨️ Transient handoff from whichever `dispatch_inner` arm actually produced messages
    /// this call (`apply_command`/`ingest_remote`/`resolve_conflict`) to `dispatch`,
    /// which drains it into the returned `CommandReceipt`. Reset at the top of every `dispatch`
    /// call; every other arm leaves it at its `Default`. Not part of the wire envelope.
    /// 🪆️ Member-addressed backbone messages this store pumped off its own transport but does
    /// NOT own: a composed document's children are replicas of their own, and only the composing app
    /// knows which live member a `(slot, child_id)` lane names. Buffered here so a pump inside an
    /// ordinary `dispatch` can never silently drop a child's remote edit, drained by
    /// {@link take_member_inbound}, and retired with the transport when the store closes.
    member_inbox: VecDeque<BackboneMessage>,
    /// 🏷️ The id of the action or command whose `Apply` this store is dispatching, stamped on the edit it mints (an
    /// amend keeps the verb of the edit it extends). Set by the dispatching runtime via
    /// {@link set_authoring_verb}; not part of the wire envelope.
    authoring_verb: Option<String>,
    /// 🐢️ Operations one turn of a deferred remote reprojection replays; `None` replays inside the ingest.
    replay_budget: Option<usize>,
    /// ⏱️ Operations one turn of a deferred local history step replays; `None` replays inside the dispatch.
    local_replay_budget: Option<usize>,
    /// 🐢️ The history change admitted but not adopted yet ([`Self::step_reprojection`]).
    pending_reprojection: Option<PendingReprojection<P, Mutation>>,
    pending_report: std::mem::ManuallyDrop<PendingCommandReport>,
    durable_group_root: std::mem::ManuallyDrop<Option<durable_group::ArtifactStoreDurableGroupRootV1<P>>>,
}

